{
  "schema_version": 1,
  "observations": [
    {
      "key": "obs_counting_sort_definition",
      "facet": "term",
      "statement": "Counting sort is a 2-pass sort algorithm.",
      "start_line": 1,
      "end_line": 11
    },
    {
      "key": "obs_efficiency_condition",
      "facet": "precondition",
      "statement": "Counting sort is efficient when the number of distinct keys is small compared to the number of items.",
      "start_line": 7,
      "end_line": 9
    },
    {
      "key": "obs_pass1_mechanism",
      "facet": "mechanism",
      "statement": "The first pass counts the occurrences of each key in an auxiliary array and makes a running total so each auxiliary entry is the number of preceding keys.",
      "start_line": 9,
      "end_line": 11
    },
    {
      "key": "obs_pass2_mechanism",
      "facet": "mechanism",
      "statement": "The second pass puts each item in its final place according to the auxiliary entry for that key.",
      "start_line": 11,
      "end_line": 11
    },
    {
      "key": "obs_generalization",
      "facet": "relation",
      "statement": "Counting sort is a kind of histogram sort.",
      "start_line": 12,
      "end_line": 15
    },
    {
      "key": "obs_bucket_vs_histogram",
      "facet": "property",
      "statement": "A bucket sort uses fixed-size buckets, whereas a histogram sort sets up buckets of exactly the right size in a first pass.",
      "start_line": 24,
      "end_line": 24
    },
    {
      "key": "obs_counting_vs_histogram",
      "facet": "property",
      "statement": "A counting sort is a histogram sort with one bucket per possible key value.",
      "start_line": 24,
      "end_line": 24
    },
    {
      "key": "obs_counting_vs_pigeonhole",
      "facet": "property",
      "statement": "A pigeonhole sort is a counting sort that moves items to the auxiliary array instead of counting them.",
      "start_line": 24,
      "end_line": 24
    },
    {
      "key": "obs_reference_source",
      "facet": "reference",
      "statement": "The entry is from the Dictionary of Algorithms and Data Structures, edited by Paul E. Black, authored by Art S. Kagel.",
      "start_line": 40,
      "end_line": 45
    }
  ],
  "claims": [],
  "questions": []
}
